CREATE TABLE IF NOT EXISTS wb_competition_cohorts (id text PRIMARY KEY, status text NOT NULL, rules_fingerprint text NOT NULL, scoring_fingerprint text NOT NULL, ai_seal_fingerprint text NOT NULL, starts_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wb_competition_members (cohort_id text NOT NULL REFERENCES wb_competition_cohorts(id), human_id text NOT NULL, verified boolean NOT NULL DEFAULT false, joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(cohort_id,human_id));
CREATE TABLE IF NOT EXISTS wb_competition_portfolios (id text PRIMARY KEY, cohort_id text NOT NULL REFERENCES wb_competition_cohorts(id), owner_id text NOT NULL, owner_type text NOT NULL CHECK(owner_type IN ('HUMAN','WEALTH_BUILDER_AI')), starting_cash numeric NOT NULL DEFAULT 100000, cash numeric NOT NULL DEFAULT 100000, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(cohort_id,owner_id));
CREATE TABLE IF NOT EXISTS wb_competition_fills (id text PRIMARY KEY, portfolio_id text NOT NULL REFERENCES wb_competition_portfolios(id), symbol text NOT NULL, side text NOT NULL CHECK(side IN ('BUY','SELL')), quantity numeric NOT NULL CHECK(quantity>0), canonical_price numeric NOT NULL CHECK(canonical_price>0), commission numeric NOT NULL DEFAULT 0, spread_cost numeric NOT NULL DEFAULT 0, slippage_cost numeric NOT NULL DEFAULT 0, filled_at timestamptz NOT NULL, decision_source text NOT NULL CHECK(decision_source IN ('HUMAN','WEALTH_BUILDER_AI')));
CREATE TABLE IF NOT EXISTS wb_research_credit_ledger (id text PRIMARY KEY, human_id text NOT NULL, delta integer NOT NULL, reason text NOT NULL, reference_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS wb_fills_portfolio_time ON wb_competition_fills(portfolio_id,filled_at);
CREATE INDEX IF NOT EXISTS wb_credits_human_time ON wb_research_credit_ledger(human_id,created_at);
